//! Fixed differential-test driver. Owned by the harness (role C).
//! Argon replaces only `src/cjson.rs`; do not edit this file.
//!
//! Mirrors backend/harness/drivers/cjson_driver.c exactly. Prints one line:
//!   `PARSE_ERROR at <offset>\n`  parse failed, offset known
//!   `PARSE_ERROR\n`              parse failed, no offset
//!   `OK\t<unformatted JSON>\n`   parse succeeded
//! Always exits 0 unless the process panics.
#![forbid(unsafe_code)]

mod cjson;

use std::io::{self, Read, Write};

fn main() {
    let mut input = Vec::new();
    if io::stdin().lock().read_to_end(&mut input).is_err() {
        eprintln!("driver: failed to read stdin");
        std::process::exit(2);
    }

    let mut line: Vec<u8> = Vec::new();
    match cjson::parse(&input) {
        Ok(value) => {
            let printed = cjson::print_unformatted(&value);
            // The C driver writes the printed C string with fputs, which stops
            // at the first NUL byte. Mirror that so the drivers are equivalent.
            let end = printed.iter().position(|&b| b == 0).unwrap_or(printed.len());
            line.extend_from_slice(b"OK\t");
            line.extend_from_slice(&printed[..end]);
            line.push(b'\n');
        }
        Err(err) => match err.offset {
            // The C driver only prints an offset inside [0, len].
            Some(off) if off <= input.len() => {
                line.extend_from_slice(format!("PARSE_ERROR at {}\n", off).as_bytes());
            }
            _ => line.extend_from_slice(b"PARSE_ERROR\n"),
        },
    }

    let mut out = io::stdout().lock();
    let _ = out.write_all(&line);
    let _ = out.flush();
}
